private theorem sumOver_netOf_eq_lineSum (accounts : List AccountId) (ls : List Line)
    (hNodup : accounts.Nodup) (hMem : ∀ l ∈ ls, l.1 ∈ accounts) :
    sumOver accounts (fun a => netOf ls a) = lineSum ls

